// frontend/src/pages/Home.jsx
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Sparkles, ArrowRight, ArrowLeft, CheckCircle2, Search, RefreshCw, ClipboardCheck, FileText, MessageSquare, ChevronDown } from 'lucide-react';

const Home = () => {
  const { user } = useAuth();

  const guideSteps = [
    { id: 1, title: '1. Xác định giá bán xe', icon: CheckCircle2, active: true },
    { id: 2, title: '2. Tìm kiếm người mua có nhu cầu phù hợp', icon: Search, active: false },
    { id: 3, title: '3. Lựa chọn hình thức bán', icon: RefreshCw, active: false },
    { id: 4, title: '4. Kiểm tra tình trạng xe', icon: CheckCircle2, active: false },
    { id: 5, title: '5. Kiểm tra giấy tờ', icon: FileText, active: false },
    { id: 6, title: '6. Đàm phán & thương lượng', icon: MessageSquare, active: false },
    { id: 7, title: '7. Hoàn tất thủ tục bán xe', icon: ClipboardCheck, active: false },
  ];

  const carBrands = [
    { id: 'toyota', name: 'TOYOTA', initial: 'T', color: 'text-red-500', logo: '/brands/logo_Toyota.jpg' },
    { id: 'honda', name: 'HONDA', initial: 'H', color: 'text-gray-800', logo: '/brands/logo_honda.jpg' },
    { id: 'hyundai', name: 'HYUNDAI', initial: 'H', color: 'text-blue-800', logo: '/brands/logo-hyundai.jpg' },
    { id: 'kia', name: 'KIA', initial: 'K', color: 'text-black', logo: '/brands/logo-kia.png' },
    { id: 'mazda', name: 'MAZDA', initial: 'M', color: 'text-gray-600', logo: '/brands/logo-mazda.jpg' },
    { id: 'mercedes', name: 'Mercedes-Benz', initial: 'M', color: 'text-gray-400', logo: '/brands/Mercedes-Benz-Logo.png' },
    { id: 'bmw', name: 'BMW', initial: 'B', color: 'text-blue-500' ,logo: '/brands/BMW.jpg'  },
    { id: 'ford', name: 'Ford', initial: 'F', color: 'text-blue-700' ,logo: '/brands/Ford_Motor_Company_Logo.svg.png'  },
    { id: 'mitsubishi', name: 'MITSUBISHI', initial: 'M', color: 'text-red-600' ,logo: '/brands/Mitsubishi-Logo-1970-present.png'  },
    { id: 'nissan', name: 'NISSAN', initial: 'N', color: 'text-gray-700' ,logo: '/brands/logo-nissan.jpg'  },
    { id: 'suzuki', name: 'SUZUKI', initial: 'S', color: 'text-blue-600' ,logo: '/brands/logo-suzuki.png'  },
    { id: 'vinfast', name: 'VINFAST', initial: 'V', color: 'text-gray-800' ,logo: '/brands/logo-vinfast.jpg'  },
    { id: 'chevrolet', name: 'CHEVROLET', initial: 'C', color: 'text-yellow-600', logo: '/brands/Chevrolet-logo.png' },
    { id: 'mg', name: 'MG', initial: 'MG', color: 'text-red-700', logo: '/brands/logo-MG.png' },
    { id: 'peugeot', name: 'PEUGEOT', initial: 'P', color: 'text-blue-900', logo: '/brands/logo-peugeot.png' }
  ];

  const slides = [
    {
      titleLine1: "Vay khó có Tima",
      titleLine2: "Bán xe vất vả, gọi liền Store Car",
      buttonDesc: "Bán xe ngay",
      hasPartner: true
    },
    {
      titleLine1: "Định giá xe ô tô",
      titleLine2: "Nhanh chóng & Chính xác bằng công nghệ AI",
      buttonDesc: "Định giá ngay",
      hasPartner: false
    },
    {
      titleLine1: "Mua bán xe lướt",
      titleLine2: "Kho xe đa dạng, có chuyên gia kiểm định",
      buttonDesc: "Tìm xe ngay",
      hasPartner: false
    },
    {
      titleLine1: "Hỗ trợ pháp lý",
      titleLine2: "Sang tên, chuyển vùng nhanh chóng an toàn",
      buttonDesc: "Xem chi tiết",
      hasPartner: false
    },
    {
      titleLine1: "Ký gửi xe cũ",
      titleLine2: "Tiếp cận hàng ngàn khách hàng tiềm năng",
      buttonDesc: "Ký gửi ngay",
      hasPartner: false
    }
  ];

  const [currentSlide, setCurrentSlide] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slides.length);
    }, 4000);
    return () => clearInterval(timer);
  }, [slides.length]);

  return (
    <div className="w-full font-sans">
      {/* Hero Section */}
      <div className="bg-[#def1ff] w-full min-h-[500px] relative overflow-hidden flex flex-col justify-center">
        <div className="max-w-7xl mx-auto px-4 w-full flex flex-col md:flex-row items-center relative z-10 pt-8 pb-16">
          {/* Left Text */}
          <div className="w-full md:w-[60%] pt-10 md:pt-0 z-20 pl-0 lg:pl-10 min-h-[300px] flex flex-col justify-center">
            <div className="mb-10 flex items-center gap-3">
              <span className="text-[#0096ff] font-bold text-3xl flex items-center gap-1 tracking-tight">
                <svg width="40" height="40" viewBox="0 0 32 32" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M7 16H25V18H7V16ZM4 20H28C29.1046 20 30 20.8954 30 22V24H2V22C2 20.8954 2.89543 20 4 20ZM7 12L9 8H23L25 12H7Z" fill="currentColor"/>
                </svg>
                store car
              </span>
              {slides[currentSlide].hasPartner && (
                <div className="flex items-center gap-3 animate-fade-in">
                  <span className="text-gray-400 text-2xl font-light">×</span>
                  <span className="text-[#ff4e00] font-extrabold text-[32px] italic tracking-tighter flex flex-col leading-none">
                    tima
                    <span className="text-[12px] text-gray-500 font-semibold not-italic tracking-normal mt-1 -ml-1">Vay trong ngày</span>
                  </span>
                </div>
              )}
            </div>
            
            <div className="min-h-[140px]">
              <h1 className="text-4xl md:text-[46px] font-bold text-[#0284ff] leading-[1.3] mb-10 tracking-tight animate-fade-in-up">
                {slides[currentSlide].titleLine1}<br/>
                {slides[currentSlide].titleLine2}
              </h1>
            </div>

            <div>
              <button className="bg-[#0096ff] hover:bg-blue-600 text-white font-semibold py-3.5 px-10 rounded-lg shadow-sm transition duration-300 text-[15px] animate-fade-in">
                {slides[currentSlide].buttonDesc}
              </button>
            </div>

            {/* Pagination Dots */}
            <div className="flex items-center gap-2 mt-12">
              {slides.map((_, index) => (
                <div 
                  key={index} 
                  onClick={() => setCurrentSlide(index)}
                  className={`rounded-full bg-[#0096ff] cursor-pointer transition-all duration-300 ease-in-out ${currentSlide === index ? 'w-3.5 h-3.5 opacity-100' : 'w-2.5 h-2.5 opacity-20 hover:opacity-50'}`}
                ></div>
              ))}
            </div>
          </div>
          
          {/* Right Image Placeholder (Cat with Money/Car) */}
          <div className="w-full md:w-[60%] absolute right-0 bottom-0 top-0 flex justify-end items-end h-full">
            <div className="w-full h-full relative flex items-center justify-end pr-10">
               {/* Stand-in for the car and cat image */}
               <div className="h-full w-full flex items-center justify-end opacity-20 pointer-events-none pr-20 pb-10">
                  <span className="text-9xl">🚗 😺</span>
               </div>
            </div>
          </div>
        </div>

        {/* Floating Right Arrow */}
        <div 
          className="absolute right-0 top-1/2 transform -translate-y-1/2 bg-blue-100/40 p-2 rounded-l-md z-20 cursor-pointer hover:bg-white transition flex items-center justify-center h-10 w-8"
          onClick={() => setCurrentSlide((prev) => (prev + 1) % slides.length)}
        >
           <span className="text-[#0096ff] text-xs font-bold leading-none">{'>_<'}</span>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="bg-[#f2f6f9] min-h-[400px] relative pb-20">
        {/* Floating Tabs */}
        <div className="flex justify-center -translate-y-7 relative z-30">
          <div className="bg-[#e6ecef] p-1.5 rounded-xl flex items-center shadow-[0_4px_10px_rgba(0,0,0,0.03)] border border-gray-100/50">
            <button className="bg-white text-gray-800 font-semibold py-3 px-10 rounded-lg shadow-sm text-sm">Bán xe</button>
            <button className="text-[#596673] font-semibold py-3 px-10 hover:text-gray-800 transition text-sm">Sở hữu xe</button>
            <button className="text-[#596673] font-semibold py-3 px-10 hover:text-gray-800 transition text-sm">Mua xe</button>
            <button className="text-[#0096ff] font-semibold py-3 px-10 flex items-center gap-2 hover:bg-blue-50/50 rounded-lg transition text-sm">
              Video AI <Sparkles size={16} className="text-orange-400 fill-orange-400" />
            </button>
          </div>
        </div>

        {/* Guide Section (Replaces Features Carousel) */}
        <div className="max-w-[1000px] mx-auto px-4 mt-20 text-center">
          <h2 className="text-[28px] font-bold text-[#3b4754] mb-4">Cẩm Nang Khi Bán Ô Tô Cũ</h2>
          
          <div className="flex justify-center items-center gap-2 mb-6 text-[22px] font-bold text-[#3b4754] tracking-tight">
            <span>Bạn đang muốn</span>
            <button className="flex items-center gap-1.5 bg-white border border-gray-200 shadow-sm rounded-lg px-4 py-2 hover:border-[#0096ff] transition group relative">
              <span className="text-[#3b4754] group-hover:text-[#0096ff] transition-colors border-b-2 border-[#3b4754] group-hover:border-[#0096ff] leading-none pb-0.5">tự bán xe</span>
              <ChevronDown size={20} strokeWidth={2.5} className="text-gray-500 group-hover:text-[#0096ff] transition-colors pt-0.5" />
            </button>
            <span>?</span>
          </div>
          
          <p className="text-[#596673] text-[15px] mb-8">
            Store Car cung cấp các tính năng miễn phí để quá trình tự bán xe của bạn diễn ra suôn sẻ và "được giá" hơn
          </p>

          <div className="flex flex-wrap justify-center items-center gap-3 max-w-[900px] mx-auto">
            {guideSteps.map((step) => {
              const Icon = step.icon;
              return (
                <div 
                  key={step.id} 
                  className={`flex items-center gap-2.5 px-4 py-2.5 rounded-lg border text-[13.5px] font-semibold cursor-pointer transition-all ${
                    step.active 
                      ? 'bg-[#eaf5ff] border-[#0096ff] text-[#0096ff]' 
                      : 'bg-white border-gray-200 text-[#596673] hover:border-[#0096ff] hover:text-[#0096ff]'
                  }`}
                >
                  <Icon size={16} strokeWidth={2} className={step.active ? 'text-[#0096ff]' : 'text-[#7dade1]'} />
                  <span>{step.title}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Brand Reference Section */}
        <div className="max-w-[1000px] mx-auto px-4 mt-16">
          <div className="bg-white rounded-3xl shadow-[0_4px_20px_rgba(0,0,0,0.03)] border border-gray-100 p-6 md:p-10">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 border-b border-gray-100 pb-6">
              <div>
                <h2 className="text-[22px] font-bold text-gray-800 mb-1">Tham khảo giá thị trường</h2>
                <p className="text-gray-500 text-[15px]">Chọn hãng để bắt đầu</p>
              </div>
              <button className="bg-[#0096ff] hover:bg-blue-600 text-white font-semibold py-2.5 px-6 rounded-lg transition text-[15px]">
                Định giá ngay
              </button>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
              {carBrands.map(brand => (
                <div key={brand.id} className="flex flex-col items-center justify-center p-5 border border-gray-100 rounded-2xl hover:shadow-[0_4px_15px_rgba(0,150,255,0.15)] hover:border-[#0096ff] transition cursor-pointer group bg-white h-[110px]">
                  {brand.logo ? (
                     <img src={brand.logo} alt={brand.name} className="w-12 h-12 object-contain mb-3 group-hover:scale-110 transition-transform duration-300" />
                  ) : (
                    <div className={`w-12 h-12 rounded-full bg-gray-50 flex items-center justify-center ${brand.color} font-black text-xl mb-3 group-hover:bg-blue-50 transition-colors`}>
                       {brand.initial}
                    </div>
                  )}
                  <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wide group-hover:text-[#0096ff] transition-colors">{brand.name}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Home;
